```jsx
import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { getProducts, deleteProduct } from '../../services/productService'
import { useAuth } from '../../hooks/useAuth'
import Table from '../../components/common/Table'
import Button from '../../components/common/Button'
import SearchInput from '../../components/forms/SearchInput'
import Badge from '../../components/common/Badge'
import { formatCurrency, formatDate } from '../../utils/formatters'
import { Plus, Edit, Trash2 } from 'lucide-react'
import toast from 'react-hot-toast'

export default function ProductList() {
  const [products, setProducts] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [category, setCategory] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const { user } = useAuth()
  const navigate = useNavigate()

  useEffect(() => { loadProducts() }, [search, category, page])

  const loadProducts = async () => {
    try {
      setLoading(true)
      const res = await getProducts({ search, category, page, limit: 10 })
      setProducts(res.data.data)
      setTotalPages(res.data.meta?.totalPages || 1)
    } catch (error) {
      toast.error('Failed to load products')
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (id, e) => {
    e.stopPropagation()
    if (!window.confirm('Delete this product?')) return
    try {
      await deleteProduct(id)
      toast.success('Product deleted')
      loadProducts()
    } catch (error) {
      toast.error('Failed to delete product')
    }
  }

  const columns = [
    { key: 'name', label: 'Name' },
    { key: 'category', label: 'Category', render: (val) => val || '-' },
    { key: 'price', label: 'Price', render: (val) => formatCurrency(val) },
    { key: 'createdAt', label: 'Created', render: (val) => formatDate(val) },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => user?.role === 'ADMIN' && (
        <div className="flex gap-2">
          <button onClick={(e) => { e.stopPropagation(); navigate(`/products/${row.id}/edit`) }}>
            <Edit className="w-4 h-4" />
          </button>
          <button onClick={(e) => handleDelete(row.id, e)} className="text-red-600">
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      )
    }
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Products</h1>
          <p className="text-gray-600">Manage your product catalog</p>
        </div>
        {user?.role === 'ADMIN' && (
          <Button onClick={() => navigate('/products/new')}>
            <Plus className="w-5 h-5 mr-2" />
            Add Product
          </Button>
        )}
      </div>

      <div className="flex gap-4">
        <SearchInput value={search} onChange={setSearch} placeholder="Search products..." />
        <select 
          value={category} 
          onChange={(e) => setCategory(e.target.value)}
          className="px-4 py-2 border rounded-lg"
        >
          <option value="">All Categories</option>
          <option value="Software">Software</option>
          <option value="Hardware">Hardware</option>
          <option value="Cloud">Cloud</option>
          <option value="Security">Security</option>
          <option value="Network">Network</option>
        </select>
      </div>

      <Table 
        columns={columns} 
        data={products} 
        loading={loading}
        onRowClick={(product) => navigate(`/products/${product.id}`)}
      />

      {totalPages > 1 && (
        <div className="flex justify-center gap-2">
          {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
            <button
              key={p}
              onClick={() => setPage(p)}
              className={`px-3 py-1 rounded ${p === page ? 'bg-blue-600 text-white' : 'bg-gray-200'}`}
            >
              {p}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}
```

