import toast from 'react-hot-toast'

const STAGE_COLORS = {
  LEAD: 'bg-gray-100 border-gray-300',
  QUALIFICATION: 'bg-blue-50 border-blue-300',
  PROPOSAL: 'bg-yellow-50 border-yellow-300',
  NEGOTIATION: 'bg-orange-50 border-orange-300',
  CLOSED_WON: 'bg-green-50 border-green-300',
  CLOSED_LOST: 'bg-red-50 border-red-300',
}

export default function DealKanban() {
  const [dealsByStage, setDealsByStage] = useState({})
  const [loading, setLoading] = useState(true)

  useEffect(() => { loadKanban() }, [])

  const loadKanban = async () => {
    try {
      const res = await getDealsKanban()
      setDealsByStage(res.data.data)
    } catch (error) {
      toast.error('Failed to load deals')
    } finally {
      setLoading(false)
    }
  }

  const handleDragStart = (e, deal) => {
    e.dataTransfer.setData('dealId', deal.id)
    e.dataTransfer.setData('currentStage', deal.stage)
  }

  const handleDrop = async (e, newStage) => {
    e.preventDefault()
    const dealId = e.dataTransfer.getData('dealId')
    const currentStage = e.dataTransfer.getData('currentStage')

    if (currentStage === newStage) return

    try {
      await updateDealStage(dealId, newStage)
      toast.success('Deal stage updated')
      loadKanban()
    } catch (error) {
      toast.error('Failed to update stage')
    }
  }

  const handleDragOver = (e) => {
    e.preventDefault()
  }

  if (loading) return <Loading />

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold">Sales Pipeline</h1>
        <p className="text-gray-600">Drag and drop deals to update stage</p>
      </div>

      <div className="flex gap-4 overflow-x-auto pb-4">
        {Object.keys(DEAL_STAGES).map(stage => (
          <div
            key={stage}
            className="flex-shrink-0 w-80"
            onDrop={(e) => handleDrop(e, stage)}
            onDragOver={handleDragOver}
          >
            <div className={`rounded-lg p-4 ${STAGE_COLORS[stage]} border-2 border-dashed`}>
              <h3 className="font-semibold mb-3 flex items-center justify-between">
                <span>{DEAL_STAGES[stage]}</span>
                <Badge>{(dealsByStage[stage] || []).length}</Badge>
              </h3>

              <div className="space-y-3 min-h-[200px]">
                {(dealsByStage[stage] || []).map(deal => (
                  <div
                    key={deal.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, deal)}
                    className="bg-white rounded-lg p-4 shadow cursor-move hover:shadow-md transition-shadow"
                  >
                    <h4 className="font-medium text-gray-800 mb-2">{deal.title}</h4>
                    <p className="text-sm text-gray-600 mb-2">{deal.customer?.companyName}</p>
                    <div className="flex items-center justify-between text-sm">
                      <span className="font-semibold text-blue-600">
                        {formatCurrency(deal.value)}
                      </span>
                      <span className="text-gray-500">
                        {deal.probability}%
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
```

