  windowMs: 15 * 60 * 1000,
  max: isProduction ? 60 : 10000,
  standardHeaders: true,
  legacyHeaders: false,
  message: { success: false, message: 'Too many API requests, please try again later' }
});

module.exports = { generalLimiter, authLimiter, apiLimiter };
